window.OL_I18N = {"lang":"it","dict":{"meta.appName":"Verifica compatibilità eSIM Openline","meta.searchTitle":"Compatibilità eSIM {q} · Openline","ui.skip":"Salta al contenuto","ui.brandAria":"Openline — Verifica se il tuo dispositivo è compatibile","ui.brandSub":"Verifica se il tuo dispositivo è compatibile","lang.label":"Lingua","lang.aria":"Cambia lingua","hero.titleHtml":"Il tuo dispositivo supporta l'<span class=\"accent\">eSIM</span>?","hero.tag":"Smartphone, tablet, smartwatch, hotspot: inserisci qualsiasi marca o modello e ti diremo subito se puoi attivare Openline.","search.placeholder":"Prova “iPhone 18 Pro”, “Galaxy Z Fold8”, “Pixel Watch 5”, “iPad Air” o un codice modello…","search.aria":"Cerca marca, modello o codice modello del dispositivo","search.clear":"Cancella ricerca","stats.devices":"dispositivi","stats.compatible":"compatibili","stats.notCompatible":"non compatibili","stats.brands":"marche","filters.label":"Filtri","filters.summaryAll":"Tutti i dispositivi · Tutte le marche","filters.explain":"Scegli uno stato di compatibilità e/o una o più marche. I filtri si combinano con la ricerca e aggiornano l'elenco in tempo reale.","filters.compat":"Compatibilità","filters.compatAria":"Filtri di compatibilità","filters.brands":"Marche","filters.brandsAria":"Filtri per marca","filters.clearAll":"Cancella tutto","filters.compatOnly":"Solo compatibili","filters.notCompatOnly":"Solo non compatibili","filters.allStatuses":"Tutti gli stati","filters.nBrands":{"many":"{n} marche","one":"{n} marca","other":"{n} marche"},"filters.matchHtml":{"many":"<strong>{n}</strong> dispositivi corrispondenti","one":"<strong>{n}</strong> dispositivo corrispondente","other":"<strong>{n}</strong> dispositivi corrispondenti"},"cat.count":{"many":"{n} dispositivi","one":"{n} dispositivo","other":"{n} dispositivi"},"results.all":"Tutti i dispositivi","results.matching":"Dispositivi corrispondenti","results.ofTotalHtml":"<strong>{n}</strong> di {total}","results.totalHtml":"<strong>{n}</strong> in totale","results.showingFirst":" · primi {max} mostrati","legend.ok":"Supporta eSIM","legend.err":"Solo SIM fisica","status.ok":"Compatibile","status.no":"Non compatibile","status.okAria":"Compatibile con eSIM","status.noAria":"Non compatibile con eSIM","note.caveatAria":"Limitazione regionale: {note}","popover.aria":"Limitazione regionale","popover.close":"Chiudi","empty.noMatchTitle":"Nessuna corrispondenza esatta.","empty.noMatchBodyHtml":"Prova solo con la marca (ad es. <em>Samsung</em>) o con il codice esatto del modello (ad es. <em>SM-S921B</em>). Se il tuo dispositivo è successivo al 2021 ed è stato acquistato al di fuori della Cina continentale, è molto probabile che supporti l'eSIM.","empty.bothTitle":"Nessun dispositivo corrisponde alla ricerca e ai filtri.","empty.bothBodyHtml":{"many":"La ricerca di <em>{q}</em> restituisce <strong>{n}</strong> dispositivi in totale, ma nessuno corrisponde ai filtri selezionati. Forse il conflitto dipende dai filtri?","one":"La ricerca di <em>{q}</em> restituisce <strong>{n}</strong> dispositivo in totale, ma non corrisponde ai filtri selezionati. Forse il conflitto dipende dai filtri?","other":"La ricerca di <em>{q}</em> restituisce <strong>{n}</strong> dispositivi in totale, ma nessuno corrisponde ai filtri selezionati. Forse il conflitto dipende dai filtri?"},"empty.filtersTitle":"Nessun dispositivo corrisponde ai tuoi filtri.","empty.filtersBody":"Prova ad allentare i filtri: combinando stati di compatibilità rari con poche marche potresti non ottenere alcun risultato.","empty.nothing":"Ancora niente qui.","empty.resetFilters":"Reimposta filtri","empty.clearSearch":"Cancella ricerca","footer.privacy":"Privacy","footer.terms":"Termini","footer.socialAria":"Openline sui social media","footer.onNetwork":"Openline su {network}","footer.handleOnNetwork":"@askopenline su {network}","footer.indexedHtml":"<b id=\"footer-total\">{n}</b> dispositivi indicizzati","region.US":"Stati Uniti","region.HK":"Hong Kong","region.CN":"Cina continentale","region.KR":"Corea del Sud","region.JP":"Giappone","region.AU":"Australia","region.TW":"Taiwan","region.SEA":"Sud-est asiatico","region.EU":"Unione Europea","region.IN":"India","region.UK":"Regno Unito","exp.carrierWatch":"Gli smartwatch Cellular ottengono l'eSIM tramite un piano per orologio dell'operatore, configurato dall'app associata sullo smartphone (app Apple Watch, Galaxy Wearable, app Pixel Watch). I codici QR delle eSIM per smartphone o da viaggio non possono essere installati direttamente sull'orologio, quindi verifica che il tuo operatore offra un piano dedicato per questo modello.","exp.gpsOnly":"Questa è la versione solo GPS. Non dispone di connettività cellulare, quindi non può utilizzare alcuna eSIM. La versione GPS + Cellular dello stesso orologio ha un numero di modello differente.","exp.cnHkMoDualNano":"Gli iPhone di questa generazione venduti in Cina continentale, Hong Kong e Macao hanno due slot nano-SIM fisici e non supportano l'eSIM. Openline non può essere installata su questi modelli. Controlla il numero del modello in Impostazioni › Generali › Info.","exp.cnDualNano":"La versione di questo telefono commercializzata in Cina continentale usa due nano-SIM fisiche e non dispone di eSIM. I modelli venduti altrove supportano l'eSIM. Controlla il numero del modello in Impostazioni › Generali › Info.","exp.cnLocalRules":"La versione per la Cina continentale supporta l'eSIM, ma gli operatori cinesi ne consentono l'attivazione solo nei punti vendita previa verifica dell'identità; inoltre, i profili eSIM esteri non possono essere installati mentre ti trovi in Cina continentale. Al di fuori della Cina, le eSIM da viaggio come Openline si installano normalmente.","exp.esimOnlyUsJpCaGulf":"I modelli venduti in Stati Uniti, Canada, Giappone, Messico e nei Paesi del Golfo non hanno il carrellino per la SIM e funzionano solo con eSIM. Negli altri mercati il telefono dispone anche di un carrellino nano-SIM, mentre i modelli per la Cina continentale potrebbero non supportare l'eSIM. Openline funziona su tutte le versioni compatibili con eSIM.","exp.noSimTray":"Questa versione non ha un carrellino per la SIM fisica: ogni linea, inclusa Openline, viene aggiunta come eSIM. Puoi memorizzare più eSIM e passare da una all'altra nelle Impostazioni.","exp.iden":"Questo dispositivo funziona sulla rete Motorola iDEN (push-to-talk Nextel / Boost), dismessa definitivamente da Sprint nel giugno 2013. Non può connettersi ad alcuna rete cellulare moderna, né con eSIM né altrimenti. Solo oggetto da museo/collezione.","exp.cdmaVerizon":"Si tratta di un dispositivo solo CDMA progettato per la vecchia rete 2G/3G CDMA di Verizon, spenta il 31 dicembre 2022. Non ha alcuno slot SIM (né fisico né eSIM): la rete CDMA autentica i dispositivi tramite ESN/MEID e non tramite SIM. Non può essere utilizzato con Openline né con alcun operatore moderno.","exp.cdmaSprint":"Questo è un dispositivo CDMA progettato per la rete legacy di Sprint, dismessa definitivamente da T-Mobile il 31 maggio 2022. I modelli Sprint più recenti hanno aggiunto LTE/GSM, ma i primi erano esclusivamente CDMA e non possono collegarsi a nessuna rete moderna, con o senza eSIM.","exp.sunset":"Questo dispositivo si affida a reti 3G o 4G datate che gli operatori hanno spento (AT&T 3G a febbraio 2022, T-Mobile a febbraio 2022, Verizon a dicembre 2022, la maggior parte del 3G europeo entro il 2025). Anche con uno slot SIM funzionante, nella maggior parte dei Paesi non troverà alcuna rete a cui connettersi.","exp.windowsPhone":"Questo dispositivo utilizza Windows Phone (o Windows 10 Mobile), piattaforma abbandonata da Microsoft nel 2019: lo Store, gli aggiornamenti di sicurezza e la maggior parte dei servizi Microsoft sono stati dismessi. Non ha hardware eSIM e non è praticamente compatibile con le app moderne. Inutilizzabile come telefono di uso quotidiano.","exp.kaios":"Si tratta di un telefono base con KaiOS. Quasi nessun dispositivo KaiOS supporta l'eSIM: utilizzano una SIM fisica (solitamente nano-SIM) e sono destinati ai mercati dei telefoni base economici solo 4G come India (JioPhone) e Africa. Openline non può essere installata su questo dispositivo.","exp.telematics":"Modulo telematico per veicoli (Tesla, BMW, Audi, ecc.) con eSIM integrata di fabbrica e saldata sulla scheda di connettività dell'auto. L'eSIM viene configurata dal costruttore e non può essere sostituita con un profilo installato dall'utente come Openline. Non riparabile dall'utente.","exp.satellite":"Dispositivo satellitare/GPS (Garmin inReach, SPOT, Zoleo, Iridium GO) che sfrutta la rete satellitare Iridium o Globalstar anziché la rete cellulare GSM/LTE. Non può usare un'eSIM in senso convenzionale: la connettività è vincolata a un abbonamento proprietario con il produttore del dispositivo.","exp.medical":"Dispositivo di emergenza medica o telesoccorso (PERS, personal emergency response). Il modulo cellulare è bloccato sul fornitore del servizio (Lively, Medical Guardian, Life Alert, Bay Alarm) e funziona solo con il relativo abbonamento di monitoraggio. Non consente l'installazione di eSIM di terze parti.","exp.rugged":"Dispositivo Samsung Enterprise / Rugged (serie Galaxy XCover) destinato al personale sul campo: magazzini, sanità, ospitalità. Supporta l'eSIM, ma l'attivazione potrebbe passare dalla configurazione MDM Samsung Knox della tua azienda. Se il dispositivo è sbloccato, Openline si installa come su qualsiasi smartphone consumer.","exp.harmony":"Dispositivo con HarmonyOS (Huawei) privo dei Google Mobile Services. L'attivazione dell'eSIM richiede in genere l'app dei servizi operatore di Huawei EMUI/HarmonyOS; i profili Openline vengono configurati tramite codice QR, ma le attivazioni basate su Google Wallet non funzionano. I modelli venduti in Cina continentale potrebbero inoltre rifiutare i profili eSIM internazionali per limitazioni del firmware CN.","exp.dualEsimOnly":"Questa variante supporta due eSIM contemporaneamente ma non ha un carrellino per la SIM fisica. Openline funziona, ma non può essere abbinata a una nano-SIM. Su alcune versioni regionali è possibile mantenere attiva una sola eSIM alla volta.","exp.euCarrier":"Alcune varianti europee di questo dispositivo con blocco operatore sono state distribuite con l'eSIM disabilitata a livello di firmware. I modelli sbloccati/global open supportano l'eSIM normalmente. Se l'attivazione non riesce, rivolgiti al tuo operatore originale.","exp.usCarrier":"Variante brandizzata da un operatore USA (AT&T, T-Mobile, Verizon, Sprint) con firmware bloccato e spesso con supporto a bande specifiche dell'operatore. L'eSIM potrebbe essere disattivata o limitata ai soli profili dell'operatore del marchio. Le unità internazionali sbloccate dello stesso modello di solito funzionano con Openline; quelle brandizzate potrebbero non farlo.","exp.verizon":"Le unità di questo Pixel a marchio Verizon sono state lanciate con l'eSIM disattivata sulla rete Verizon. Le unità sbloccate e quelle di altri operatori supportano l'eSIM normalmente.","exp.googleFi":"Su questa generazione di Pixel, l'eSIM era disponibile negli Stati Uniti solo con Google Fi. Gli altri operatori richiedevano una SIM fisica. Le unità globali sbloccate supportano l'eSIM ovunque.","exp.usEsimOnly":"Sulle unità di questo iPhone acquistate negli Stati Uniti, Apple ha rimosso completamente il carrellino per la SIM fisica: è obbligatorio usare una eSIM. Altrove il telefono ha anche il carrellino per la SIM fisica oltre all'eSIM. Openline funziona comunque in entrambi i casi.","exp.cnOnly":"Questo dispositivo viene fornito con firmware per il mercato interno cinese. Il supporto eSIM è presente sulla carta, ma i profili internazionali spesso non si attivano al di fuori della Cina continentale. Se hai intenzione di viaggiare, verifica l'attivazione dell'eSIM con il venditore prima dell'acquisto.","exp.jpDomestic":"I telefoni brandizzati dagli operatori giapponesi (NTT DoCoMo, au, SoftBank, Rakuten) sono di solito vincolati alle bande del Giappone. L'hardware eSIM funziona in Giappone; l'attivazione all'estero dipende dalla sovrapposizione delle bande con le reti locali.","exp.regionLocked":"L'attivazione dell'eSIM su questo dispositivo è vincolata a livello di firmware a una specifica regione. Accetta unicamente profili eSIM di operatori del Paese o dell'area in cui è stato venduto.","exp.krOnly":"Modello venduto esclusivamente in Corea del Sud e che usa le bande degli operatori KT/SKT/LGU+. L'hardware eSIM è presente, ma l'attivazione all'estero non è affidabile.","exp.foldable":"Dispositivo pieghevole: lo slot eSIM è presente, ma alcune varianti pieghevoli vendute in Cina non supportano l'eSIM internazionale. Verifica che il codice modello corrisponda alla versione globale (SKU).","exp.hotspot":"Hotspot Wi-Fi portatile / router MiFi e non uno smartphone. Accetta una eSIM per condividere i dati cellulari con gli altri dispositivi. Openline si configura come su uno smartphone.","exp.simTrayOnly":"Questo dispositivo ha una radio cellulare, ma accetta esclusivamente una nano-SIM o micro-SIM fisica: non c'è alcun chip eSIM. Non puoi installare Openline come eSIM; ti serve invece un piano con SIM fisica.","exp.wifiOnly":"Questa variante è solo Wi-Fi: non ha modem cellulare. Non può installare alcuna eSIM. Cerca la versione LTE / 5G / Cellular dello stesso modello.","exp.ereader":"Questo e-reader ha un modem cellulare integrato di fabbrica, legato al piano dati gratuito del produttore (Amazon Whispernet, B&N nook, ecc.). La eSIM/SIM non è configurabile dall'utente: non puoi inserire un profilo Openline.","exp.cellularEsimOnly":"Questa variante ha connettività cellulare solo tramite eSIM: sul dispositivo non c'è il carrellino per la SIM fisica. Openline si installa direttamente tramite codice QR.","exp.unverifiedVariant":"I nostri dati associano questo codice modello a più famiglie di prodotti. Di solito significa che Apple, Samsung o Google hanno riutilizzato un codice interno per generazioni diverse, oppure che un modello regionale è stato rinominato. Openline dovrebbe comunque funzionare, ma se il codice modello sulla confezione non corrisponde al dispositivo che stai guardando, verifica con il produttore prima dell'acquisto.","exp.crossBrand":"Questo codice modello compare anche su un dispositivo di un'altra marca (Vivo/iQOO, Xiaomi/POCO, Nokia/HMD, Nubia/ZTE, ecc.). Di solito si tratta di marchi dello stesso gruppo: l'hardware è spesso identico, a volte rimarchiato, ma il supporto eSIM e la certificazione degli operatori possono differire tra le due marche. Verifica sulla confezione originale del tuo dispositivo.","exp.modelUnverified":"Non disponiamo di un codice modello/part number ufficiale per questo dispositivo, di solito perché si tratta di un wearable, modulo telematico per veicoli, hotspot o accessorio il cui SKU non è pubblico. Il supporto eSIM è indicato nella scheda tecnica del produttore, ma Openline non può associare un codice hardware specifico per garantire la compatibilità. Verifica con il produttore prima di fare affidamento su questa informazione.","exp.ambiguous":"Il nome del prodotto è molto breve (“13”, “F7”, “M6”…) e si confonde facilmente con modelli omonimi di altre marche o generazioni. Controlla la marca e il codice modello sul dispositivo per assicurarti che questa voce corrisponda a ciò che possiedi.","exp.cnFirmware":"Questa unità viene fornita con firmware per il mercato interno cinese. L'hardware eSIM è presente, ma il firmware cinese spesso blocca l'attivazione dei profili eSIM internazionali. Se desideri utilizzare Openline fuori dalla Cina continentale, verifica con il venditore che il firmware non sia bloccato per regione prima dell'acquisto.","exp.regionExcluded":"Le unità di questo dispositivo vendute nelle seguenti aree escono senza hardware eSIM, quindi funziona solo il carrellino per la SIM fisica: {regions}. Altrove l'eSIM è supportata e Openline si attiva normalmente. Se l'hai acquistato all'estero o tramite un importatore parallelo, confronta il codice modello con l'elenco del produttore.","note.3G free":"3G gratuito","note.3G/4G":"3G/4G","note.AU/JP/TW excluded":"AU/JP/TW esclusi","note.Ambiguous name":"Nome ambiguo","note.CDMA":"CDMA","note.CN firmware":"Firmware CN","note.CN/HK excluded":"CN/HK esclusi","note.CN/HK/MO: dual nano-SIM":"CN/HK/MO: doppia nano-SIM","note.CN/IN":"CN/IN","note.CN/IN dual-eSIM only":"CN/IN solo dual-eSIM","note.CN: dual nano-SIM":"CN: doppia nano-SIM","note.CN: local eSIM rules":"CN: regole eSIM locali","note.Carrier watch plan":"Piano operatore smartwatch","note.Cross-brand model code":"Codice modello tra marche","note.E-reader":"E-reader","note.Enterprise rugged":"Rugged aziendale","note.Foldable":"Pieghevole","note.GPS only":"Solo GPS","note.GPS/satellite tracker":"Tracker GPS/satellitare","note.Google Fi/US only":"Solo Google Fi/US","note.HarmonyOS":"HarmonyOS","note.JP domestic band lock":"Blocco bande JP","note.KR only":"Solo KR","note.KR/CN":"KR/CN","note.KaiOS feature phone":"Feature phone KaiOS","note.Medical alert":"Allarme medico","note.Mobile hotspot":"Hotspot portatile","note.Model code unverified":"Codice non verificato","note.Nextel/Boost":"Nextel/Boost","note.No eSIM hardware":"Nessun hardware eSIM","note.No eSIM in most regions":"No eSIM in molti Paesi","note.Not on Verizon/Sprint":"Non su Verizon/Sprint","note.SEA excluded":"SEA escluso","note.SIM tray only":"Solo carrellino SIM","note.Sprint":"Sprint","note.US carrier variant":"Variante operatore US","note.US model excluded":"Modello US escluso","note.US variant excluded":"Variante US esclusa","note.US/HK excluded":"US/HK esclusi","note.US/JP: eSIM ok":"US/JP: eSIM ok","note.US: eSIM only":"US: solo eSIM","note.Unverified variant":"Variante non verificata","note.Vehicle telematics":"Telematica veicoli","note.Verizon":"Verizon","note.Verizon US no eSIM":"Verizon US senza eSIM","note.Verizon-only 5G":"5G solo Verizon","note.Wi-Fi + Cellular only":"Solo Wi-Fi + Cellular","note.Wi-Fi + free 4G":"Wi-Fi + 4G gratuito","note.Wi-Fi only":"Solo Wi-Fi","note.Wi-Fi only in most regions":"Solo Wi-Fi in molti Paesi","note.Wi-Fi/3G":"Wi-Fi/3G","note.Windows Phone":"Windows Phone","note.deprecated":"obsoleto","note.dual-eSIM in EU":"dual-eSIM in UE","note.eSIM only":"Solo eSIM","note.eSIM only (no SIM tray)":"Solo eSIM (senza carrellino)","note.eSIM only in US/JP/CA/Gulf":"Solo eSIM in US/JP/CA/Golfo","note.eSIM only via Google Fi":"Solo eSIM con Google Fi","note.iDEN":"iDEN","note.sunset":"rete dismessa"}};
